#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 1e6 + 5;

int n, f[2][3];
bool a[N], b[N];

void init() {}

void solve()
{
	cin >> n;
	for (int i = 1; i <= n; ++i)
	{
		char ch;
		cin >> ch;
		a[i] = ch - 48;
	}
	for (int i = 1; i <= n; ++i)
	{
		char ch;
		cin >> ch;
		b[i] = ch - 48;
	}
	for (int i = 1; i <= n; ++i)
	{
		for (int j = 0; j < 3; ++j)
		{
			f[i][j] = 1e9;
			for (int k = 0; k < 3; ++k)
				f[i][j] = min(f[i][j], f[i - 1][k] + (j != 2 && j != k) + (!(j == 2 ? a[i] ^ b[i] : j ^ b[i]) && (k == 2 ? a[i - 1] ^ b[i - 1] : k ^ b[i - 1])));
		}
	}
	cout << min({f[n][0], f[n][1], f[n][2]}) << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}

